-    }
-
-    /// Unwrap a `FuncKey::ArrayToWasmTrampoline` or else panic.
-    pub fn unwrap_array_to_wasm_trampoline(self) -> (StaticModuleIndex, DefinedFuncIndex) {
-        match self {
-            Self::ArrayToWasmTrampoline(module, def_func) => (module, def_func),
